INSERT INTO businesses (id, slug, name, short_description, description, timezone, status, verification_status, claim_status, version, created_by, created_at, updated_at, published_at) VALUES
('b0000000-0000-0000-0000-000000000001', 'naderi-cafe', 'کافه و هتل نادری', 'کافه نوستالژیک و تاریخی تهران', 'یکی از قدیمی‌ترین و اصیل‌ترین کافه‌های تهران واقع در خیابان جمهوری با فضای نوستالژیک و قهوه اصیل.', 'Asia/Tehran', 'PUBLISHED', 'VERIFIED', 'CLAIMED', 1, '00000000-0000-0000-0000-000000000002', NOW(), NOW(), NOW()),
('b0000000-0000-0000-0000-000000000002', 'orkideh-restaurant', 'رستوران سنتی ارکیده (آرژانتین)', 'بهترین کباب و غذای اصیل ایرانی', 'مجموعه رستوران‌های ارکیده با بیش از ۶۵ سال تجربه، محیطی مجلل و غذاهای باکیفیت ایرانی همراه با موسیقی زنده.', 'Asia/Tehran', 'PUBLISHED', 'VERIFIED', 'CLAIMED', 1, '00000000-0000-0000-0000-000000000002', NOW(), NOW(), NOW()),
('b0000000-0000-0000-0000-000000000003', 'perperook-pizza-vanak', 'پیتزا پرپروک (شعبه ونک)', 'پیتزای پنجره‌ای و برگر ذغالی', 'اولین ارائه‌دهنده پیتزای پنجره‌ای در ایران با سس‌های اختصاصی و کیفیت ماندگار در میدان ونک.', 'Asia/Tehran', 'PUBLISHED', 'VERIFIED', 'CLAIMED', 1, '00000000-0000-0000-0000-000000000002', NOW(), NOW(), NOW()),
('b0000000-0000-0000-0000-000000000004', 'valiasr-medical-clinic', 'درمانگاه شبانه‌روزی ولیعصر', 'خدمات پزشکی، اورژانس و تزریقات ۲۴ ساعته', 'ارائه کلیه خدمات عمومی، تخصصی، آزمایشگاه، نوار قلب و تزریقات به صورت شبانه‌روزی.', 'Asia/Tehran', 'PUBLISHED', 'VERIFIED', 'CLAIMED', 1, '00000000-0000-0000-0000-000000000003', NOW(), NOW(), NOW()),
('b0000000-0000-0000-0000-000000000005', 'kazemi-dental-clinic', 'کلینیک دندانپزشکی دکتر کاظمی', 'مرکز تخصصی ایمپلنت و زیبایی دندان', 'انجام خدمات تخصصی ارتودنسی، لمینت سرامیکی و کاشت دندان با بروزترین تجهیزات دیجیتال در سعادت‌آباد.', 'Asia/Tehran', 'PUBLISHED', 'VERIFIED', 'NOT_CLAIMED', 1, '00000000-0000-0000-0000-000000000003', NOW(), NOW(), NOW()),
('b0000000-0000-0000-0000-000000000006', 'benz-bmw-repair-center', 'تعمیرگاه تخصصی آلمانی سنتر', 'تعمیرات تخصصی بنز، بی‌ام‌و و پورشه', 'عیب‌یابی پیشرفته با دستگاه‌های اصلی دیاگ، تعمیر موتور، گیربکس اتوماتیک و سرویس‌های دوره‌ای در خیابان سهروردی.', 'Asia/Tehran', 'PUBLISHED', 'VERIFIED', 'CLAIMED', 1, '00000000-0000-0000-0000-000000000002', NOW(), NOW(), NOW()),
('b0000000-0000-0000-0000-000000000007', 'king-barbershop-tajrish', 'پیرایش و سالن مردانه کینگ', 'اصلاح، پاکسازی پوست و گریم تخصصی', 'سالن VIP آقایان با خدمات کوتاهی ژورنالی، اسپا، کراتینه و آماده‌سازی داماد در میدان تجریش.', 'Asia/Tehran', 'PUBLISHED', 'UNVERIFIED', 'NOT_CLAIMED', 1, '00000000-0000-0000-0000-000000000002', NOW(), NOW(), NOW()),
('b0000000-0000-0000-0000-000000000008', 'hyperstar-bakri', 'هایپراستار (شعبه باکری)', 'بزرگ‌ترین هایپرمارکت غرب تهران', 'عرضه کلیه اقلام خوراکی، میوه و سبزیجات تازه، پوشاک و لوازم دیجیتال با تخفیف‌های روزانه.', 'Asia/Tehran', 'PUBLISHED', 'VERIFIED', 'CLAIMED', 1, '00000000-0000-0000-0000-000000000003', NOW(), NOW(), NOW()),
('b0000000-0000-0000-0000-000000000009', 'apple-care-tehran', 'اپل استور و مرکز خدمات پایتخت', 'مرکز تخصصی تعمیرات و فروش محصولات اپل', 'فروش و خدمات پس از فروش آیفون، مک‌بوک و آیپد با قطعات اورجینال در مجتمع پایتخت میرداماد.', 'Asia/Tehran', 'PUBLISHED', 'VERIFIED', 'CLAIMED', 1, '00000000-0000-0000-0000-000000000002', NOW(), NOW(), NOW()),
('b0000000-0000-0000-0000-000000000010', 'oxygen-vip-gym', 'باشگاه ورزشی اکسیژن پرو', 'مجموعه ورزشی مجهز به استخر و بدنسازی', 'دستگاه‌های پیشرفته بدنسازی، مربیان بین‌المللی، سونا، جکوزی و بوفه رژیمی در نیاوران.', 'Asia/Tehran', 'PUBLISHED', 'VERIFIED', 'CLAIMED', 1, '00000000-0000-0000-0000-000000000003', NOW(), NOW(), NOW()),
('b0000000-0000-0000-0000-000000000011', 'sam-cafe-freshteh', 'سام کافه (شعبه فرشته)', 'فضای مدرن برای دورکاری و نوشیدن قهوه', 'ارائه قهوه با دانه‌های تازه رست‌شده و باریستاهای حرفه‌ای در محیطی با طراحی صنعتی در خیابان فرشته.', 'Asia/Tehran', 'PUBLISHED', 'VERIFIED', 'CLAIMED', 1, '00000000-0000-0000-0000-000000000002', NOW(), NOW(), NOW()),
('b0000000-0000-0000-0000-000000000012', 'shila-fastfood-sattarkhan', 'فست‌فود شیلا (شعبه ستارخان)', 'هات‌داگ مخصوص و پیتزا دونر', 'طعم ماندگار هات‌داگ‌های تنوری و ساندویچ‌های ویژه شیلا در غرب تهران.', 'Asia/Tehran', 'PUBLISHED', 'UNVERIFIED', 'NOT_CLAIMED', 1, '00000000-0000-0000-0000-000000000002', NOW(), NOW(), NOW())
